import { ArgumentsHost, Catch, ExceptionFilter, HttpException, HttpStatus } from '@nestjs/common';
import { Prisma } from '@campusfind/database';
import { randomUUID } from 'node:crypto';
import type { Request, Response } from 'express';
import { z } from '@campusfind/contracts';
export function parse<T>(schema: z.ZodType<T, any, any>, input: unknown): T {
  const result = schema.safeParse(input);
  if (!result.success)
    throw new HttpException(
      {
        code: 'VALIDATION_ERROR',
        message: 'Оруулсан өгөгдөл буруу',
        details: result.error.issues.map((x) => ({ path: x.path, message: x.message })),
      },
      400,
    );
  return result.data;
}
export function fail(status: number, code: string, message: string): never {
  throw new HttpException({ code, message }, status);
}
@Catch()
export class ApiExceptionFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    const req = host.switchToHttp().getRequest<Request>();
    const res = host.switchToHttp().getResponse<Response>();
    const requestId = String(res.getHeader('X-Request-Id') ?? randomUUID());
    let status = 500,
      code = 'INTERNAL_ERROR',
      message = 'Серверийн алдаа',
      details: unknown;
    if (exception instanceof HttpException) {
      status = exception.getStatus();
      const body = exception.getResponse();
      if (typeof body === 'object' && body) {
        const b = body as Record<string, unknown>;
        code = String(b.code ?? HttpStatus[status] ?? 'ERROR');
        message = String(b.message ?? 'Хүсэлт амжилтгүй');
        details = b.details;
      } else {
        code = String(HttpStatus[status]);
        message = String(body);
      }
    } else if (
      exception instanceof Prisma.PrismaClientKnownRequestError &&
      exception.code === 'P2002'
    ) {
      status = 409;
      code = 'CONFLICT';
      message = 'Ижил утгатай бүртгэл байна';
    }
    if (status === 500)
      console.error(
        JSON.stringify({
          requestId,
          method: req.method,
          path: req.path,
          error: exception instanceof Error ? exception.name : 'UnknownError',
        }),
      );
    res
      .status(status)
      .json({ error: { code, message, requestId, ...(details ? { details } : {}) } });
  }
}

import 'reflect-metadata';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Test } from '@nestjs/testing';
import { PrismaClient } from '@campusfind/database';
import { AppModule } from '../../src/app.module';
import { MailService } from '../../src/modules/auth/mail.service';
import { configureApp } from '../../src/app';
// Explicitly fails without an isolated test database; never silently skips a required check.
test('PostgreSQL: register → verify → login → posts → logout, lockout and blocked session', async () => {
  if (!process.env.TEST_DATABASE_URL?.includes('campusfind_test'))
    throw new Error('TEST_DATABASE_URL нь campusfind_test гэсэн тусдаа DB байх ёстой');
  process.env.DATABASE_URL = process.env.TEST_DATABASE_URL;
  process.env.UNIVERSITY_EMAIL_DOMAINS = 'example.edu';
  const db = new PrismaClient(),
    tokens = new Map<string, string>();
  const mod = await Test.createTestingModule({ imports: [AppModule] })
    .overrideProvider(MailService)
    .useValue({
      sendVerification: async (email: string, token: string) => {
        tokens.set(email, token);
      },
    })
    .compile();
  const app = mod.createNestApplication({ logger: false });
  configureApp(app);
  await app.listen(0, '127.0.0.1');
  const base = (await app.getUrl()) + '/api/v1';
  const email = `test-${Date.now()}@example.edu`,
    password = 'correct horse battery staple';
  const send = (path: string, body: unknown, cookie = '') =>
    fetch(base + path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-CampusFind': 'web', Cookie: cookie },
      body: JSON.stringify(body),
    });
  let userId: string | undefined, postId: string | undefined;
  try {
    assert.equal(
      (
        await send('/auth/register', {
          displayName: 'Тест',
          email,
          studentCode: 'T' + String(Date.now()).slice(-9),
          password,
        })
      ).status,
      202,
    );
    const user = await db.user.findUniqueOrThrow({ where: { email } });
    userId = user.id;
    assert.notEqual(user.passwordHash, password);
    assert.equal((await send('/auth/login', { email, password })).status, 403);
    assert.equal((await send('/auth/verify-email', { token: tokens.get(email) })).status, 200);
    assert.equal((await send('/auth/verify-email', { token: tokens.get(email) })).status, 400);
    for (let i = 0; i < 5; i++)
      assert.equal(
        (await send('/auth/login', { email, password: 'wrong' })).status,
        i === 4 ? 429 : 401,
      );
    assert.equal((await send('/auth/login', { email, password })).status, 429);
    await db.user.update({
      where: { id: user.id },
      data: { lockedUntil: new Date(Date.now() - 1000) },
    });
    const login = await send('/auth/login', { email, password });
    assert.equal(login.status, 200);
    const cookie = login.headers.get('set-cookie')!.split(';')[0];
    assert(login.headers.get('set-cookie')!.toLowerCase().includes('httponly'));
    const payload = {
      type: 'FOUND',
      title: 'Түлхүүр',
      description: 'Номын сан',
      category: 'KEYS',
      location: 'LIBRARY',
      occurredOn: '2026-09-20',
      handoverMethod: 'GUARD',
    };
    assert.equal((await send('/posts', payload, cookie)).status, 400);
    const created = await send('/posts', { ...payload, guardLocation: 'MAIN' }, cookie);
    assert.equal(created.status, 201);
    const value = await created.json();
    postId = value.data.id;
    assert(!JSON.stringify(value).includes(user.studentCode));
    const list = await fetch(base + '/posts', { headers: { Cookie: cookie } });
    assert.equal(list.status, 200);
    assert((await list.json()).data.items.some((p: any) => p.id === postId));
    await db.user.update({ where: { id: user.id }, data: { blockedAt: new Date() } });
    assert.equal((await fetch(base + '/users/me', { headers: { Cookie: cookie } })).status, 403);
    await db.user.update({ where: { id: user.id }, data: { blockedAt: null } });
    assert.equal((await send('/auth/logout', {}, cookie)).status, 200);
    assert.equal((await fetch(base + '/users/me', { headers: { Cookie: cookie } })).status, 401);
  } finally {
    if (postId) await db.post.delete({ where: { id: postId } });
    if (userId) await db.user.delete({ where: { id: userId } });
    await app.close();
    await db.$disconnect();
  }
});

import 'reflect-metadata';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Test } from '@nestjs/testing';
import { AppModule } from '../../src/app.module';
import { configureApp } from '../../src/app';
import { DbService } from '../../src/db/db.module';
import { MailService } from '../../src/modules/auth/mail.service';
import { hashToken } from '../../src/common/security';
const token = 'a'.repeat(64),
  user = {
    id: '11111111-1111-4111-8111-111111111111',
    displayName: 'Тест',
    email: 'test@example.edu',
    studentCode: 'B232270021',
    role: 'MEMBER',
    emailVerifiedAt: new Date(),
    blockedAt: null,
    passwordHash: 'not-public',
  };
test('HTTP foundation: routes, CSRF, privacy, auth, explicit planned errors', async (t) => {
  process.env.DATABASE_URL = 'postgresql://unused';
  process.env.UNIVERSITY_EMAIL_DOMAINS = 'example.edu';
  const db = {
    session: {
      findUnique: async ({ where }: any) =>
        where.tokenHash === hashToken(token)
          ? { user, tokenHash: where.tokenHash, expiresAt: new Date(Date.now() + 60000) }
          : null,
    },
    $queryRaw: async () => [1],
    $disconnect: async () => {},
  };
  const module = await Test.createTestingModule({ imports: [AppModule] })
    .overrideProvider(DbService)
    .useValue(db)
    .overrideProvider(MailService)
    .useValue({ sendVerification: async () => {} })
    .compile();
  const app = module.createNestApplication({ logger: false });
  configureApp(app);
  await app.listen(0, '127.0.0.1');
  const base = await app.getUrl();
  const get = (path: string, auth = false) =>
    fetch(base + '/api/v1' + path, {
      headers: auth ? { Cookie: `campusfind_session=${token}` } : {},
    });
  try {
    await t.test('liveness works without database or authentication', async () => {
      const r = await get('/health');
      assert.equal(r.status, 200);
      assert.equal((await r.json()).data.status, 'ok');
    });
    await t.test('register route validates rather than falling into reservation', async () => {
      const r = await fetch(base + '/api/v1/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-CampusFind': 'web' },
        body: '{}',
      });
      assert.equal(r.status, 400);
      assert.equal((await r.json()).error.code, 'VALIDATION_ERROR');
    });
    await t.test('mutation rejects missing CSRF header', async () => {
      const r = await fetch(base + '/api/v1/auth/login', { method: 'POST' });
      assert.equal(r.status, 403);
    });
    await t.test('foreign origin is rejected even with header', async () => {
      const r = await fetch(base + '/api/v1/auth/login', {
        method: 'POST',
        headers: { 'X-CampusFind': 'web', Origin: 'https://evil.test' },
      });
      assert.equal(r.status, 403);
    });
    await t.test('posts need authentication', async () =>
      assert.equal((await get('/posts')).status, 401),
    );
    await t.test('me never leaks full code, email or hash', async () => {
      const r = await get('/users/me', true);
      assert.equal(r.status, 200);
      const body = await r.text();
      assert(body.includes('B23****'));
      assert(!body.includes('B232270021'));
      assert(!body.includes('passwordHash'));
      assert(!body.includes('test@example.edu'));
    });
    await t.test('planned feature returns 501 instead of fake success', async () => {
      const r = await get('/chats', true);
      assert.equal(r.status, 501);
      assert.equal((await r.json()).error.code, 'NOT_IMPLEMENTED');
    });
    await t.test('data-layer search seam becomes HTTP 501 without querying DB', async () => {
      const r = await get('/posts?q=keys', true);
      assert.equal(r.status, 501);
      assert.equal((await r.json()).error.code, 'NOT_IMPLEMENTED');
    });
    await t.test(
      'data-layer filter seam becomes HTTP 501 without leaking internal errors',
      async () => {
        const r = await get('/posts?category=KEYS', true);
        assert.equal(r.status, 501);
        assert.equal((await r.json()).error.code, 'NOT_IMPLEMENTED');
      },
    );
    await t.test('nonadmin cannot enter admin reservation', async () =>
      assert.equal((await get('/admin/reports', true)).status, 403),
    );
    await t.test('unknown authenticated route returns uniform 404', async () => {
      const r = await get('/not-a-route', true);
      assert.equal(r.status, 404);
      assert((await r.json()).error.requestId);
    });
  } finally {
    await app.close();
  }
});
